public function rules(): array {
    return [
        'name'    => ['required', 'string', 'max:100'],
        'email'   => ['required', 'email', 'max:150', Rule::unique('customers', 'email')->where('tenant_id', 1)],
        'country' => ['required', Rule::in(['BD','NO','DE','US','IN'])],
    ];
}

// CustomerController
public function store(StoreCustomerRequest $r): JsonResponse {
    $c = Customer::create($r->validated() + ['tenant_id' => 1, 'created_at' => now()]);
    return CustomerResource::make($c)->response()->setStatusCode(201);
}
public function show(Customer $customer): CustomerResource { return CustomerResource::make($customer); }

// CustomerResource
public function toArray(Request $request): array {
    return ['id' => $this->id, 'name' => $this->name, 'country' => $this->country,
            'email' => $this->when($request->user()?->id === $this->id, $this->email)];
}

// tests
public function test_creates_customer(): void {
    $this->postJson('/api/v1/customers', ['name' => 'Zia', 'email' => 'z@x.com', 'country' => 'BD'])
         ->assertCreated()->assertJsonPath('data.name', 'Zia')->assertJsonMissingPath('data.email');
}
public function test_rejects_bad_country(): void {
    $this->postJson('/api/v1/customers', ['name' => 'Zia', 'email' => 'z@x.com', 'country' => 'XX'])
         ->assertUnprocessable()->assertJsonValidationErrors(['country']);
}
public function test_404_for_missing(): void { $this->getJson('/api/v1/customers/999999999')->assertNotFound(); }

